// Review gate 6 (spec 6.3): the gate-5 scenes over the whole file-icon fixture, generated by scripts/review/gate-6-job.mjs.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { buildFileIconTheme, readFileIconInputs } from '../scripts/lib/file-icons-build.mjs';
import { BREADCRUMBS_FILE, FILE_PAGES, FIXTURE, FOLDER_GROUPS, QUICK_OPEN_PAGES, TAB_PAGES, fixtureEntries, gate6Job } from '../scripts/review/gate-6-job.mjs';

const root = path.resolve(import.meta.dirname, '..');
const json = (file) => JSON.parse(fs.readFileSync(path.join(root, file), 'utf8'));
const job = () => json('review/jobs/gate-6.json');
const scene = (name) => job().scenes.find((candidate) => candidate.name === name);
const entries = fixtureEntries(root);
const isFolder = (entry) => fs.statSync(path.join(root, FIXTURE, entry)).isDirectory();
const ON_SCREEN = /r\.left >= box\.left && r\.right <= box\.right && r\.top >= box\.top && r\.bottom <= box\.bottom/;
// VS Code's file icon lookup (spec 6): a file name first, then the longest dot-suffix, then the default file.
const iconOf = (theme, name) => {
  const lower = name.toLowerCase();
  if (theme.fileNames?.[lower]) return theme.fileNames[lower];
  const parts = lower.split('.');
  for (let index = 1; index < parts.length; index += 1) {
    const suffix = parts.slice(index).join('.');
    if (theme.fileExtensions?.[suffix]) return theme.fileExtensions[suffix];
  }
  return theme.file;
};

test('review/jobs/gate-6.json is the generator\'s job for the committed fixture (node scripts/review/gate-6-job.mjs)', () => {
  assert.deepEqual(job(), gate6Job(entries));
});

test('gate 6 opens the file-icon fixture in all four color themes at 100% and 200%, one sheet per scene, no scene overriding an icon or color theme', () => {
  const { workspace, passes, scenes, commitSheets } = job();
  assert.equal(workspace, 'review/workspace-files');
  assert.deepEqual(passes, [{ name: 'main', vsix: ['spellbound-main.vsix'], scales: [1, 2] }]);
  assert.equal(scenes.length, 24);
  assert.deepEqual(commitSheets, scenes.map(({ name, crops }) => `main-${name}-${crops[0].name}`));
  for (const { name, settings = {} } of scenes) {
    for (const key of ['workbench.iconTheme', 'workbench.productIconTheme', 'workbench.colorTheme']) assert.ok(!(key in settings), `${name} keeps ${key}`);
  }
});

test('the Explorer pages walk the whole fixture: every file on one closed page of at most 13 rows, every folder on one closed and one open page', () => {
  const files = entries.filter((entry) => !isFolder(entry));
  const folders = entries.filter(isFolder);
  const paged = Object.values(FILE_PAGES).flat();
  assert.deepEqual([...paged].sort(), [...files].sort(), 'every top-level file once');
  assert.equal(new Set(paged).size, paged.length);
  for (const [name, page] of Object.entries(FILE_PAGES)) assert.ok(page.length <= 13, `${name}: ${page.length} rows`);
  assert.deepEqual(FOLDER_GROUPS.flat().sort(), [...folders].sort(), 'every folder once');
  for (const group of FOLDER_GROUPS) assert.equal(group.length, 5, 'five folders and their children: ten rows');
  for (const name of [...Object.keys(FILE_PAGES), 'explorer-folders', 'explorer-folders-2', 'explorer-open', 'explorer-open-2', 'explorer-open-3', 'explorer-open-4']) {
    const { settings, setup } = scene(name);
    const shown = entries.filter((entry) => !settings['files.exclude'][entry]);
    assert.ok(Object.values(settings['files.exclude']).every((value) => value === true), name);
    const wait = setup.at(-1).waitFor;
    assert.match(wait, /const box = list\.getBoundingClientRect\(\)/, `${name}: every row inside the tree, not behind the Outline header`);
    for (const entry of shown) assert.ok(wait.includes(`"${entry.toLowerCase()}-name-${isFolder(entry) ? 'folder' : 'file'}-icon"`), `${name}: ${entry}`);
  }
});

test('the open Explorer pages reveal each folder by opening its child, one match per typed path and quick-open history off, and wait with the tree focused', () => {
  FOLDER_GROUPS.forEach((group, index) => {
    const name = `explorer-open${index ? `-${index + 1}` : ''}`;
    const { settings, setup, teardown } = scene(name);
    const opened = setup.filter((step) => step.insert).map((step) => step.insert.split('/')[0]);
    assert.deepEqual(opened, group, name);
    for (const folder of group) {
      assert.deepEqual(group.filter((other) => other !== folder && other.includes(folder)), [], `${name}: no other folder of the page contains ${folder}`);
    }
    assert.deepEqual(entries.filter((entry) => !settings['files.exclude'][entry]), [...group].sort(), `${name}: only its folders are visible to quick open`);
    assert.equal(settings['search.quickOpen.includeHistory'], false, `${name}: no history ahead of the typed path`);
    assert.equal(settings['search.exclude']?.['**/node_modules'] === false, group.includes('node_modules'), `${name}: node_modules reachable by quick open only where it is opened`);
    const wait = setup.at(-1).waitFor;
    assert.ok(wait.includes('rows.length === 10') && wait.includes('view.contains(document.activeElement)'), name);
    assert.deepEqual(teardown.map((step) => step.press), ['alt+shift+F5', 'alt+shift+F9']);
  });
});

test('the tab pages open every file drawing gate 6 adds, four to a page with both side bars closed, beside the gate-5 ts gem and json keyring', () => {
  const { map, sources } = readFileIconInputs(root);
  const { theme } = buildFileIconTheme(map, sources);
  const shown = new Set(Object.values(TAB_PAGES).flat().map((file) => iconOf(theme, file)));
  const fileDrawings = Object.entries(map.drawings).filter(([, entry]) => !entry.default && !entry.folderNames && !entry.folderNamesExpanded).map(([name]) => name);
  // snake and contract are gate-5 drawings shown in gate 5's tabs scene; the ts gem and the keyring stand beside their look-alikes.
  assert.deepEqual(fileDrawings.filter((name) => !shown.has(name)), ['snake', 'contract']);
  for (const [name, files] of Object.entries(TAB_PAGES)) {
    const { setup } = scene(name);
    assert.deepEqual(setup.filter((step) => step.insert).map((step) => step.insert), files, name);
    assert.deepEqual(entries.filter((entry) => !scene(name).settings['files.exclude'][entry]), [...files].sort(), `${name}: only its files are visible to quick open`);
    assert.equal(scene(name).settings['search.quickOpen.includeHistory'], false, name);
    assert.deepEqual(setup.slice(0, 2).map((step) => step.press), ['ctrl+alt+shift+F8', 'ctrl+alt+shift+F9'], `${name}: both side bars closed first`);
    assert.ok(setup.at(-1).waitFor.includes(`c.querySelectorAll('.tab').length === ${files.length}`), name);
    assert.match(setup.at(-1).waitFor, ON_SCREEN);
  }
  assert.equal(iconOf(theme, BREADCRUMBS_FILE), 'grimoire-open');
  assert.deepEqual(entries.filter((entry) => !scene('breadcrumbs').settings['files.exclude'][entry]), [BREADCRUMBS_FILE]);
});

test('every gate-6 quick open types its file, waits for that file\'s row to be focused, then presses Enter; the quick-open pages show six framed sample files', () => {
  let opened = 0;
  for (const { name, setup } of job().scenes) {
    setup.forEach((step, index) => {
      if (step.press !== 'alt+shift+F7') return;
      const [typed, wait, enter] = setup.slice(index + 1, index + 4);
      assert.ok(setup.slice(0, index).some((earlier) => earlier.waitFor === "!!document.activeElement?.closest('.part.editor')"), `${name}: the editor group holds the focus first`);
      assert.equal(wait.until, 'quick-input-row', name);
      if (name in QUICK_OPEN_PAGES) {
        assert.deepEqual([typed.insert, wait.file, enter.press], ['sample.', undefined, undefined], name);
      } else {
        assert.deepEqual([wait.file, enter.press], [typed.insert.split('/').at(-1), 'Enter'], `${name}: ${typed.insert}`);
        opened += 1;
      }
    });
  }
  assert.equal(opened, 20 + 28 + 1, 'four open pages of five, seven tab pages of four, the breadcrumbs');
  for (const [name, files] of Object.entries(QUICK_OPEN_PAGES)) {
    const { settings, setup } = scene(name);
    assert.ok(files.length === 6 && files.every((file) => file.startsWith('sample.') && entries.includes(file)), name);
    assert.deepEqual(entries.filter((entry) => !settings['files.exclude'][entry]), [...files].sort(), `${name}: only its files`);
    assert.match(setup.at(-1).waitFor, ON_SCREEN);
  }
});
